class Animal {
    void speak() {
        System.out.println("Tiếng động vật");
    }
}

class Dog extends Animal {
    // Bảo viết hàm này và bảo đây là Ghi đè (Overriding):
    void speak(int times) {
        System.out.println("Gâu gâu " + times + " lần");
    }
}

public class Main {
    public static void main(String[] args) {
        Animal pet = new Dog();
        pet.speak(); // Gọi hàm nào?
    }
}
